#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
// Reduction over the "middle" mode of a logically 3-D contiguous tensor:
//   X has logical shape (outer, R, inner), strides (R*inner, inner, 1)
//   Y has logical shape (outer, inner),      strides (inner, 1)
//   Y(o, w) = min_r X(o, r, w)
//
// Optimization: 256-bit-per-row vectorized global loads. Each thread
// owns EIGHT consecutive elements of the inner mode and keeps eight
// independent accumulators (one per element) across the reduced mode.
// For 16-byte-aligned rows this is two float4 loads; for misaligned
// rows (possible when inner is not a multiple of 4) the eight floats
// are fetched with three overlapping, fully aligned float4 loads (the
// extra window overlaps the neighbor thread's windows and is served
// from L1) plus register-level word selects. Owning twice as many
// elements per thread amortizes the row-misalignment handling and the
// overlapping window over twice as many bytes, cutting the average
// number of global-load instructions per 16 bytes from ~1.75 to
// ~1.375 when inner is not a multiple of 4. The misalignment is
// uniform across the whole warp/block (it depends only on the row's
// flat offset), so there is no divergence. A guard on the remaining
// element count keeps the speculative third load inside the
// allocation; only the rare tail near the very end of the tensor
// falls back to scalar loads. The row loop is unrolled by 4 so each
// thread keeps 8-12 independent vector loads in flight (memory-level
// parallelism) with a register footprint comparable to the previous
// 8x4 unroll. The reduced mode R is still split into two contiguous
// half-ranges processed by the two halves of a 512-thread block, and
// the two partial minima are combined through shared memory before
// the final stores.
__device__ __forceinline__ void load8f(const float* __restrict__ p,
                                       const float* __restrict__ endp,
                                       float& e0, float& e1, float& e2, float& e3,
                                       float& e4, float& e5, float& e6, float& e7) {
  const uintptr_t addr = reinterpret_cast<uintptr_t>(p);
  const int mis = (int)((addr & 15) >> 2);
  if (mis == 0) {
    const float4 v0 = *reinterpret_cast<const float4*>(p);
    const float4 v1 = *(reinterpret_cast<const float4*>(p) + 1);
    e0 = v0.x; e1 = v0.y; e2 = v0.z; e3 = v0.w;
    e4 = v1.x; e5 = v1.y; e6 = v1.z; e7 = v1.w;
  } else if (endp - p >= 11) {
    // Three aligned 16-byte windows cover p[0..7]; the extra words
    // overlap the neighbor threads' windows and are served from L1.
    const float4* q = reinterpret_cast<const float4*>(addr & ~(uintptr_t)15);
    const float4 v0 = q[0];
    const float4 v1 = q[1];
    const float4 v2 = q[2];
    if (mis == 1) {
      e0 = v0.y; e1 = v0.z; e2 = v0.w; e3 = v1.x;
      e4 = v1.y; e5 = v1.z; e6 = v1.w; e7 = v2.x;
    } else if (mis == 2) {
      e0 = v0.z; e1 = v0.w; e2 = v1.x; e3 = v1.y;
      e4 = v1.z; e5 = v1.w; e6 = v2.x; e7 = v2.y;
    } else {
      e0 = v0.w; e1 = v1.x; e2 = v1.y; e3 = v1.z;
      e4 = v1.w; e5 = v2.x; e6 = v2.y; e7 = v2.z;
    }
  } else {
    e0 = p[0]; e1 = p[1]; e2 = p[2]; e3 = p[3];
    e4 = p[4]; e5 = p[5]; e6 = p[6]; e7 = p[7];
  }
}
__device__ __forceinline__ void store8f(float* __restrict__ p,
                                        float a0, float a1, float a2, float a3,
                                        float a4, float a5, float a6, float a7) {
  const uintptr_t addr = reinterpret_cast<uintptr_t>(p);
  if ((addr & 15) == 0) {
    float4* q = reinterpret_cast<float4*>(p);
    q[0] = make_float4(a0, a1, a2, a3);
    q[1] = make_float4(a4, a5, a6, a7);
  } else {
    p[0] = a0; p[1] = a1; p[2] = a2; p[3] = a3;
    p[4] = a4; p[5] = a5; p[6] = a6; p[7] = a7;
  }
}
