        float b10, b11, b12, b13, b14, b15, b16, b17;
        float b20, b21, b22, b23, b24, b25, b26, b27;
        float b30, b31, b32, b33, b34, b35, b36, b37;
        load8f(p0, endp, b00, b01, b02, b03, b04, b05, b06, b07);
        load8f(p1, endp, b10, b11, b12, b13, b14, b15, b16, b17);
        load8f(p2, endp, b20, b21, b22, b23, b24, b25, b26, b27);
        load8f(p3, endp, b30, b31, b32, b33, b34, b35, b36, b37);
        a0 = fminf(a0, fminf(fminf(b00, b10), fminf(b20, b30)));
        a1 = fminf(a1, fminf(fminf(b01, b11), fminf(b21, b31)));
        a2 = fminf(a2, fminf(fminf(b02, b12), fminf(b22, b32)));
        a3 = fminf(a3, fminf(fminf(b03, b13), fminf(b23, b33)));
        a4 = fminf(a4, fminf(fminf(b04, b14), fminf(b24, b34)));
        a5 = fminf(a5, fminf(fminf(b05, b15), fminf(b25, b35)));
        a6 = fminf(a6, fminf(fminf(b06, b16), fminf(b26, b36)));
        a7 = fminf(a7, fminf(fminf(b07, b17), fminf(b27, b37)));
        p += 4 * inner;
      }
      for (; r < r_end; ++r) {
        float b00, b01, b02, b03, b04, b05, b06, b07;
        load8f(p, endp, b00, b01, b02, b03, b04, b05, b06, b07);
        a0 = fminf(a0, b00);
        a1 = fminf(a1, b01);
        a2 = fminf(a2, b02);
        a3 = fminf(a3, b03);
        a4 = fminf(a4, b04);
        a5 = fminf(a5, b05);
        a6 = fminf(a6, b06);
        a7 = fminf(a7, b07);
        p += inner;
      }
    } else {
      // Ragged tail of the inner mode (inner not a multiple of 8):
      // only the first nv (1..7) elements of this thread are valid.
      for (; r < r_end; ++r) {
        a0 = fminf(a0, (float)p[0]);
        if (nv > 1) a1 = fminf(a1, (float)p[1]);
        if (nv > 2) a2 = fminf(a2, (float)p[2]);
        if (nv > 3) a3 = fminf(a3, (float)p[3]);
        if (nv > 4) a4 = fminf(a4, (float)p[4]);
        if (nv > 5) a5 = fminf(a5, (float)p[5]);
        if (nv > 6) a6 = fminf(a6, (float)p[6]);
        if (nv > 7) a7 = fminf(a7, (float)p[7]);
        p += inner;
      }
    }
