  // Combine the two half-range partial minima through shared memory,
  // then a single store per output element.
  __shared__ float partial[Threads * 8];
  if (half) {
    float* s = partial + lane * 8;
    s[0] = a0; s[1] = a1; s[2] = a2; s[3] = a3;
    s[4] = a4; s[5] = a5; s[6] = a6; s[7] = a7;
  }
  __syncthreads();
  if (!half && w0 < inner) {
    const float* s = partial + lane * 8;
    a0 = fminf(a0, s[0]);
    a1 = fminf(a1, s[1]);
    a2 = fminf(a2, s[2]);
    a3 = fminf(a3, s[3]);
    a4 = fminf(a4, s[4]);
    a5 = fminf(a5, s[5]);
    a6 = fminf(a6, s[6]);
    a7 = fminf(a7, s[7]);
