      if (nv > 2) mY(o, w0 + 2) = static_cast<T>(a2);
      if (nv > 3) mY(o, w0 + 3) = static_cast<T>(a3);
      if (nv > 4) mY(o, w0 + 4) = static_cast<T>(a4);
      if (nv > 5) mY(o, w0 + 5) = static_cast<T>(a5);
      if (nv > 6) mY(o, w0 + 6) = static_cast<T>(a6);
      if (nv > 7) mY(o, w0 + 7) = static_cast<T>(a7);
